              "description": "Precise file, section, or page location.",
              "type": "string"
            },
            "name": {
              "description": "Element name.",
              "type": "string"
            },
            "what_it_is": {
              "description": "Neutral explanation of the element.",
              "type": "string"
            }
          },
          "required": [
            "name",
            "what_it_is",
            "location"
          ],
          "type": "object"
        },
        "type": "array"
      },
      "overview": {
        "description": "One-paragraph summary of what the input is and what it is for.",
        "type": "string"
      },
      "quality_notes": {
        "description": "Gaps, garbled text, missing pieces, or other input-quality limitations.",
        "items": {
          "type": "string"
        },
        "type": "array"
      },
      "structure": {
        "description": "Every major part of the input in a useful reading order.",
        "items": {
          "properties": {
            "location": {
              "description": "Precise file, section, or page location.",
              "type": "string"
            },
            "part": {
              "description": "Name of the major part.",
              "type": "string"
            },
            "role": {
              "description": "What the part does or covers.",
              "type": "string"
            }
          },
          "required": [
            "part",
            "role",
            "location"
          ],
          "type": "object"
        },
        "type": "array"
      }
    },
    "required": [
      "overview",
      "structure",
      "key_elements",
      "conventions",
      "cross_references",
      "quality_notes"
    ],
    "title": "General input survey",
    "type": "object"
  },
  "outputs": {
