    {
      "agents": [
        "claude"
      ],
      "context": {
        "include": [
          {
            "kind": "step",
            "parts": [
              "report"
            ],
            "step": "analysis"
          }
        ]
      },
      "enabled": true,
      "id": "synthesis",
      "label": "Synthesis",
      "phase": "sequential",
      "prompt": "Synthesize the independent analyses into a single prioritized report. Resolve disagreements explicitly and preserve supporting evidence.\n\n{prior_outputs}",
      "tools": []
    }
  ],
  "type": "profile",
  "use_orientation": true,
  "variables": []
}

